<?php
declare(strict_types=1);
require __DIR__.'/backend-sard-regression.php';
$pdo=seed();$GLOBALS['auth']['role']='supervisor';$GLOBALS['input']=['student_id'=>'student-1','assignment_id'=>'old','status'=>'frozen'];
$before=$pdo->query('SELECT * FROM segment_completions')->fetchAll();
handle_patch_assignment();$frozen=$pdo->query("SELECT * FROM student_plan_assignments WHERE id='old'")->fetch();
handle_patch_assignment();check($GLOBALS['response']['updated']===0&&$pdo->query("SELECT frozen_at FROM student_plan_assignments WHERE id='old'")->fetchColumn()===$frozen['frozen_at'],'duplicate freeze retains its original timestamp and confirms the same assignment');
$GLOBALS['input']=['student_id'=>'student-1','plan_id'=>'next','expected_assignment_id'=>'old','start_segment_index'=>2];handle_assign_plan();$new=$GLOBALS['response']['assignment_id'];
check((int)$pdo->query("SELECT COUNT(*) FROM student_plan_assignments WHERE status IN ('active','frozen')")->fetchColumn()===1,'replacing a frozen plan leaves exactly one current assignment');
check($pdo->query("SELECT status FROM student_plan_assignments WHERE id='old'")->fetchColumn()==='transferred'&&$pdo->query('SELECT * FROM segment_completions')->fetchAll()===$before,'frozen history and exact old completions survive replacement');
$GLOBALS['input']=['student_id'=>'student-1','assignment_id'=>'old','status'=>'active'];expectFailure(fn()=>handle_patch_assignment(),'تغيّرت خطة الطالب');
check($pdo->query("SELECT status FROM student_plan_assignments WHERE id='$new'")->fetchColumn()==='active','old resume cannot reactivate an old assignment or change the new one');
unset($GLOBALS['input']['assignment_id']);expectFailure(fn()=>handle_patch_assignment(),'معرّف التعيين');
$pdo=seed();$GLOBALS['auth']['role']='supervisor';$pdo->exec("INSERT INTO student_plan_assignments(id,student_id,plan_id,start_segment_index,status) VALUES('duplicate','student-1','current',1,'frozen')");$GLOBALS['input']=['student_id'=>'student-1','assignment_id'=>'old','status'=>'frozen'];expectFailure(fn()=>handle_patch_assignment(),'تعيينات حالية متعددة');
check((int)$pdo->query("SELECT COUNT(*) FROM student_plan_assignments WHERE status IN ('active','frozen')")->fetchColumn()===2,'ambiguous legacy assignments remain untouched for review');
$pdo=seed();$GLOBALS['auth']['role']='supervisor';$pdo->exec("CREATE TRIGGER reject_freeze BEFORE UPDATE ON student_plan_assignments WHEN NEW.status='frozen' BEGIN SELECT RAISE(ABORT,'fixture freeze failure'); END");$GLOBALS['input']=['student_id'=>'student-1','assignment_id'=>'old','status'=>'frozen'];expectFailure(fn()=>handle_patch_assignment(),'fixture freeze failure');check(activePlan($pdo)==='current','failed freeze rolls back without altering the plan');
foreach([0,-1,1.5,'bad',99] as $start){$pdo=seed();$GLOBALS['auth']['role']='supervisor';$GLOBALS['input']['start_segment_index']=$start;expectFailure(fn()=>handle_assign_plan(),$start===99?'غير موجود':'عددًا صحيحًا');check(activePlan($pdo)==='current'&&(int)$pdo->query('SELECT COUNT(*) FROM student_plan_assignments')->fetchColumn()===1,'invalid start never closes the current plan');}
$pdo=seed();$GLOBALS['auth']['role']='supervisor';$pdo->exec("UPDATE plan_segments SET segment_index=3 WHERE plan_id='next' AND segment_index=2");$GLOBALS['input']['start_segment_index']=2;expectFailure(fn()=>handle_assign_plan(),'غير موجود');$GLOBALS['input']['start_segment_index']=3;handle_assign_plan();check((int)$pdo->query("SELECT start_segment_index FROM student_plan_assignments WHERE status='active'")->fetchColumn()===3,'real middle segment is accepted without assuming a contiguous catalog');
$pdo=seed();$pdo->exec("UPDATE student_plan_assignments SET status='frozen'");expectFailure(fn()=>handle_assign_plan(),'المسمّع مخوّل');check((int)$pdo->query('SELECT COUNT(*) FROM student_plan_assignments')->fetchColumn()===1,'musammi still cannot advance a frozen assignment');
foreach(['teacher','secretary','musammi','student','parent'] as $role){$pdo=seed();$GLOBALS['auth']['role']=$role;$GLOBALS['input']=['student_id'=>'student-1','assignment_id'=>'old','status'=>'frozen'];expectFailure(fn()=>handle_patch_assignment(),'Forbidden');}
